function TROP_POW_FAST(A, k):
    e <- k + 1                      # field-friendly indexing
    base <- A
    result <- undefined
    while e > 0:
        if e is odd:
            result <- base if result undefined else TROP_MUL(result, base)
        e <- floor(e / 2)
        if e > 0:
            base <- TROP_MUL(base, base)   # tropical squaring
    return result

function TROP_MUL(A, B):
    for i, j:
        (A (X) B)[i][j] <- min over k of (A[i][k] + B[k][j])
    return A (X) B

function TROPICAL_DH(A, a_secret, b_secret):
    P_A <- TROP_POW(A, a_secret)        # Alice publishes A^{(X)(a+1)}
    P_B <- TROP_POW(A, b_secret)        # Bob publishes   A^{(X)(b+1)}
    key_alice <- TROP_POW(P_B, a_secret)   # (A^b)^a
    key_bob   <- TROP_POW(P_A, b_secret)   # (A^a)^b
    assert key_alice == key_bob            # by tropMatPow_comm
    return key_alice

function MIN_CYCLE_MEAN(A):
    best <- +infinity
    for L in 1..n:
        P <- TROP_POW(A, L-1)            # paths of exactly L edges
        best <- min(best, min_i P[i][i] / L)
    return best

function TDLP_RECOVER(A, Y):            # Y = A^{(X)m}
    P <- A
    for m in 0..search_bound:
        if P == Y: return m
        P <- TROP_MUL(A, P)
    return None
